-- Permission vocabulary and system roles of the equity module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the equity permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('dividend:create'::text, 'dividend'::text, 'create'::text, 'Create dividend'::text),
            ('dividend:delete'::text, 'dividend'::text, 'delete'::text, 'Delete dividend'::text),
            ('dividend:purge'::text, 'dividend'::text, 'purge'::text, 'Purge dividend'::text),
            ('dividend:read'::text, 'dividend'::text, 'read'::text, 'Read dividend'::text),
            ('dividend:restore'::text, 'dividend'::text, 'restore'::text, 'Restore dividend'::text),
            ('dividend:update'::text, 'dividend'::text, 'update'::text, 'Update dividend'::text),
            ('share_class:create'::text, 'share_class'::text, 'create'::text, 'Create share class'::text),
            ('share_class:delete'::text, 'share_class'::text, 'delete'::text, 'Delete share class'::text),
            ('share_class:purge'::text, 'share_class'::text, 'purge'::text, 'Purge share class'::text),
            ('share_class:read'::text, 'share_class'::text, 'read'::text, 'Read share class'::text),
            ('share_class:restore'::text, 'share_class'::text, 'restore'::text, 'Restore share class'::text),
            ('share_class:update'::text, 'share_class'::text, 'update'::text, 'Update share class'::text),
            ('share_transaction:create'::text, 'share_transaction'::text, 'create'::text, 'Create share transaction'::text),
            ('share_transaction:delete'::text, 'share_transaction'::text, 'delete'::text, 'Delete share transaction'::text),
            ('share_transaction:purge'::text, 'share_transaction'::text, 'purge'::text, 'Purge share transaction'::text),
            ('share_transaction:read'::text, 'share_transaction'::text, 'read'::text, 'Read share transaction'::text),
            ('share_transaction:restore'::text, 'share_transaction'::text, 'restore'::text, 'Restore share transaction'::text),
            ('share_transaction:update'::text, 'share_transaction'::text, 'update'::text, 'Update share transaction'::text),
            ('shareholder:create'::text, 'shareholder'::text, 'create'::text, 'Create shareholder'::text),
            ('shareholder:delete'::text, 'shareholder'::text, 'delete'::text, 'Delete shareholder'::text),
            ('shareholder:purge'::text, 'shareholder'::text, 'purge'::text, 'Purge shareholder'::text),
            ('shareholder:read'::text, 'shareholder'::text, 'read'::text, 'Read shareholder'::text),
            ('shareholder:restore'::text, 'shareholder'::text, 'restore'::text, 'Restore shareholder'::text),
            ('shareholder:update'::text, 'shareholder'::text, 'update'::text, 'Update shareholder'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('dividend:create'::text, 'dividend'::text, 'create'::text, 'Create dividend'::text),
            ('dividend:delete'::text, 'dividend'::text, 'delete'::text, 'Delete dividend'::text),
            ('dividend:purge'::text, 'dividend'::text, 'purge'::text, 'Purge dividend'::text),
            ('dividend:read'::text, 'dividend'::text, 'read'::text, 'Read dividend'::text),
            ('dividend:restore'::text, 'dividend'::text, 'restore'::text, 'Restore dividend'::text),
            ('dividend:update'::text, 'dividend'::text, 'update'::text, 'Update dividend'::text),
            ('share_class:create'::text, 'share_class'::text, 'create'::text, 'Create share class'::text),
            ('share_class:delete'::text, 'share_class'::text, 'delete'::text, 'Delete share class'::text),
            ('share_class:purge'::text, 'share_class'::text, 'purge'::text, 'Purge share class'::text),
            ('share_class:read'::text, 'share_class'::text, 'read'::text, 'Read share class'::text),
            ('share_class:restore'::text, 'share_class'::text, 'restore'::text, 'Restore share class'::text),
            ('share_class:update'::text, 'share_class'::text, 'update'::text, 'Update share class'::text),
            ('share_transaction:create'::text, 'share_transaction'::text, 'create'::text, 'Create share transaction'::text),
            ('share_transaction:delete'::text, 'share_transaction'::text, 'delete'::text, 'Delete share transaction'::text),
            ('share_transaction:purge'::text, 'share_transaction'::text, 'purge'::text, 'Purge share transaction'::text),
            ('share_transaction:read'::text, 'share_transaction'::text, 'read'::text, 'Read share transaction'::text),
            ('share_transaction:restore'::text, 'share_transaction'::text, 'restore'::text, 'Restore share transaction'::text),
            ('share_transaction:update'::text, 'share_transaction'::text, 'update'::text, 'Update share transaction'::text),
            ('shareholder:create'::text, 'shareholder'::text, 'create'::text, 'Create shareholder'::text),
            ('shareholder:delete'::text, 'shareholder'::text, 'delete'::text, 'Delete shareholder'::text),
            ('shareholder:purge'::text, 'shareholder'::text, 'purge'::text, 'Purge shareholder'::text),
            ('shareholder:read'::text, 'shareholder'::text, 'read'::text, 'Read shareholder'::text),
            ('shareholder:restore'::text, 'shareholder'::text, 'restore'::text, 'Restore shareholder'::text),
            ('shareholder:update'::text, 'shareholder'::text, 'update'::text, 'Update shareholder'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
